// @match        https://*.shuffle.site/*
// @match        https://*.shuffle.club/*
// @match        https://*.shuffle.gold/*
// @match        https://*.shuffle.game/*
// @match        https://*.shuffle.casino/*
// @match        https://*.shuffle.digital/*
// @match        https://*.shuffle71.com/*
// @match        https://*.shuffle888.com/*
// @match        https://*.shuffle1060.com/*
// @match        https://*.shuffle1061.com/*
// @match        https://*.disorder4.com/*
