// rotation does not strand every user until the script is republished.
// @include      /^https:\/\/([a-z0-9-]+\.)?shuffle\d{1,5}\.com\/.*/i
// @include      /^https:\/\/([a-z0-9-]+\.)?disorder\d{1,3}\.com\/.*/i
